  --color-neutral-600: #4b5563;
  --color-neutral-700: #374151;
  --color-neutral-800: #1f2937;
  --color-neutral-900: #111827;
  --color-text-primary: #111827;
  --color-text-secondary: #6b7280;
  --color-border: #e5e7eb;
  --color-focus-ring: #2563eb;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
  --shadow-xl: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 200ms cubic-bezier(0.4, 0, 0.2, 1);
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-neutral-50: #0f172a;
    --color-neutral-100: #1e293b;
    --color-neutral-200: #334155;
    --color-neutral-300: #475569;
    --color-neutral-600: #cbd5e1;
    --color-neutral-700: #e2e8f0;
    --color-neutral-800: #f1f5f9;
    --color-neutral-900: #f8fafc;
    --color-text-primary: #f8fafc;
    --color-text-secondary: #cbd5e1;
    --color-border: #334155;
  }
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--color-text-primary);
  background: var(--color-neutral-50);
  overflow-x: hidden;
}

/* ===========================
   Header
   =========================== */

.app-header {
  background: linear-gradient(135deg, var(--color-primary), var(--color-primary-focus));
  color: white;
  padding: 2rem 1.5rem;
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 10;
}

.app-header h1 {
  font-size: 1.875rem;
  font-weight: 700;
  letter-spacing: -0.025em;
}

/* ===========================
   Main Content
   =========================== */

.app-main {
  padding: 2rem 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
}

.image-gallery h2 {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 1.5rem;
  color: var(--color-neutral-900);
}

/* ===========================
   Gallery Grid
   =========================== */

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}

@media (max-width: 640px) {
  .gallery-grid {
    grid-template-columns: 1fr;
  }
}

/* ===========================
   Image Card
   =========================== */

.image-card {
  background: white;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
  display: flex;
  flex-direction: column;
}

@media (prefers-color-scheme: dark) {
  .image-card {
    background: var(--color-neutral-100);
  }
}

.image-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.image-container {
  position: relative;
  width: 100%;
  padding-bottom: 100%;
  overflow: hidden;
  background: var(--color-neutral-100);
}

.image-container img {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.image-info {
  padding: 1.25rem;
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.image-info h3 {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--color-neutral-900);
}

.image-meta {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin-bottom: 1rem;
}

/* ===========================
   Buttons
   =========================== */

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* Delete Button in Card */
.btn-delete {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1rem;
  background: var(--color-neutral-100);
  color: var(--color-danger);
  border: 1.5px solid var(--color-danger);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 500;
  transition: all var(--transition-base);
}

.btn-delete:hover:not(:disabled) {
  background: var(--color-danger);
  color: white;
}

.btn-delete:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 2px;
}

.btn-delete:active:not(:disabled) {
  transform: scale(0.98);
}

.btn-delete svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

