 * Handle dialog close event (also triggered by Escape key)
 */
dialog.addEventListener('close', (event) => {
  // Restore focus if dialog was closed via Escape or other means
  if (triggerElement && document.contains(triggerElement)) {
    triggerElement.focus();
  }

  // Cleanup for non-native fallback
