+/**
+ * Modal Dialog Controller
+ * Manages open/close state and focus for the delete confirmation dialog
+ */
+
+const dialog = document.getElementById('delete-confirmation-dialog');
+const triggers = document.querySelectorAll('.trigger');
+let triggerElement = null;
+
+/**
+ * Open the dialog - show modal and manage focus
+ */
+function openDialog(trigger) {
+  triggerElement = trigger;
+  
+  if (dialog.showModal) {
+    dialog.showModal();
+  } else {
+    // Fallback for browsers without showModal support
+    dialog.setAttribute('open', '');
+    document.body.style.overflow = 'hidden';
+  }
+
+  // Focus on the secondary button (Cancel) to avoid accidental deletion
+  const cancelButton = dialog.querySelector('[value="cancel"]');
+  if (cancelButton) {
+    cancelButton.focus();
+  }
+}
+
+/**
+ * Close the dialog and restore focus
+ */
+function closeDialog(result) {
+  dialog.close(result);
+
+  // Restore focus to the trigger button
+  if (triggerElement && document.contains(triggerElement)) {
+    triggerElement.focus();
+  }
+
+  triggerElement = null;
+}
+
+/**
+ * Handle cancel button click
+ */
+dialog.querySelector('[value="cancel"]').addEventListener('click', () => {
+  closeDialog('cancel');
+});
+
+/**
+ * Handle delete button click
+ */
+dialog.querySelector('[value="delete"]').addEventListener('click', () => {
+  // In a real app, you would delete the image here
+  console.log('Image deleted');
+  closeDialog('delete');
+});
+
+/**
+ * Handle dialog close event (also triggered by Escape key)
+ */
+dialog.addEventListener('close', (event) => {
+  // Restore focus if dialog was closed via Escape or other means
+  if (triggerElement && document.contains(triggerElement)) {
+    triggerElement.focus();
+  }
+
+  // Cleanup for non-native fallback
+  if (dialog.hasAttribute('open')) {
+    dialog.removeAttribute('open');
+    document.body.style.overflow = '';
+  }
+
+  triggerElement = null;
+});
+
+/**
+ * Attach click listeners to all delete triggers
+ */
+triggers.forEach((trigger) => {
+  trigger.addEventListener('click', (e) => {
+    e.preventDefault();
+    openDialog(trigger);
+  });
+
+  // Enable keyboard support (Enter/Space) in addition to click
+  trigger.addEventListener('keypress', (e) => {
+    if (e.key === 'Enter' || e.key === ' ') {
+      e.preventDefault();
+      openDialog(trigger);
+    }
+  });
+});
+
+/**
+ * Handle Escape key to close dialog
+ * (Native dialog element handles this automatically, but included for clarity)
+ */
+document.addEventListener('keydown', (e) => {
+  if (e.key === 'Escape' && dialog.hasAttribute('open')) {
+    closeDialog('cancelled');
+  }
+});
+
