const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  let browser;
  try {
    browser = await chromium.launch();
    const page = await browser.newPage();

    // Read and load the HTML
    const htmlPath = path.join(__dirname, 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf-8');

    await page.setContent(html, { waitUntil: 'load' });

    // Add axe-core
    await page.addScriptTag({ path: '/tmp/axe.min.js' });

    console.log('=== Test 1: Closed State ===');
    let results = await page.evaluate(async () => {
      return await window.axe.run();
    });

    let wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    let bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(`WCAG violations: ${wcag.length}, Best-practice: ${bp.length}, Passes: ${results.passes.length}`);
    if (wcag.length > 0) {
      wcag.forEach(v => {
        console.log(`  - ${v.id}: ${v.description}`);
        console.log(`    Targets: ${v.nodes.map(n => n.target).join(', ')}`);
      });
    }

    console.log('\n=== Test 2: Dialog Open State ===');

    // Open the dialog
    await page.evaluate(() => {
      const dialog = document.getElementById('delete-confirmation-dialog');
      if (dialog.showModal) {
        dialog.showModal();
      } else {
        dialog.setAttribute('open', '');
      }
    });

    // Wait for dialog to be visible
    await page.waitForTimeout(500);

    results = await page.evaluate(async () => {
      return await window.axe.run();
    });

    wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(`WCAG violations: ${wcag.length}, Best-practice: ${bp.length}, Passes: ${results.passes.length}`);
    if (wcag.length > 0) {
      wcag.forEach(v => {
        console.log(`  - ${v.id}: ${v.description}`);
        console.log(`    Targets: ${v.nodes.map(n => n.target).join(', ')}`);
      });
    }

    console.log('\n=== Test 3: Keyboard Navigation ===');

    // Test keyboard focus
    const focusTest = await page.evaluate(() => {
      const triggers = document.querySelectorAll('.trigger');
      const focusable = [];

      triggers.forEach((el, idx) => {
        focusable.push({
          index: idx,
          tag: el.tagName,
          class: el.className,
          ariaLabel: el.getAttribute('aria-label'),
          hasType: el.hasAttribute('type'),
          type: el.getAttribute('type')
        });
      });

      return focusable;
    });

    console.log('Trigger buttons found:', focusable.length);
    focusable.forEach((item, i) => {
      console.log(`  ${i+1}. <${item.tag}> class="${item.class}" aria-label="${item.ariaLabel}" type="${item.type}"`);
    });

    console.log('\n=== Test 4: Dialog Semantics ===');

    const dialogSemantics = await page.evaluate(() => {
      const dialog = document.getElementById('delete-confirmation-dialog');
      return {
        tag: dialog.tagName,
        ariaLabelledby: dialog.getAttribute('aria-labelledby'),
        ariaDescribedby: dialog.getAttribute('aria-describedby'),
        hasHeading: !!dialog.querySelector('#delete-dialog-heading'),
        headingText: dialog.querySelector('#delete-dialog-heading')?.textContent,
        hasDescription: !!dialog.querySelector('#delete-dialog-description'),
        descriptionText: dialog.querySelector('#delete-dialog-description')?.textContent,
        buttons: Array.from(dialog.querySelectorAll('button')).map(b => ({
          text: b.textContent.trim(),
          type: b.getAttribute('type'),
          value: b.getAttribute('value'),
          class: b.className
        }))
      };
    });

    console.log('Dialog tag:', dialogSemantics.tag);
    console.log('aria-labelledby:', dialogSemantics.ariaLabelledby);
    console.log('aria-describedby:', dialogSemantics.ariaDescribedby);
    console.log('Heading:', dialogSemantics.headingText);
    console.log('Description:', dialogSemantics.descriptionText);
    console.log('Buttons:', dialogSemantics.buttons.length);
    dialogSemantics.buttons.forEach((btn, i) => {
      console.log(`  ${i+1}. "${btn.text}" (value="${btn.value}", type="${btn.type}")`);
    });

    await browser.close();
    console.log('\n✓ All manual tests completed successfully');
    process.exit(0);
  } catch (error) {
    console.error('Test error:', error.message);
    if (browser) await browser.close();
    process.exit(1);
  }
})();

